svg.script:
var svg, userInfo, warning, henLink, objktInfo, timestamp, objktLink;
var w, h, users, viewerWallet;

// Get all the relevant html elements
svg = document.querySelector("svg");
userInfo = document.querySelector("#userInfo");
warning = document.querySelector("#warning");
henLink = document.querySelector("#henLink");
objktInfo = document.querySelector("#objktInfo");
timestamp = document.querySelector("#timestamp");
objktLink = document.querySelector("#objktLink");

// Update the svg size to the window size
var updateSvgSize = function() {
    w = window.innerWidth;
    h = window.innerHeight;
    svg.setAttribute("viewBox", "0 0 "+ w.toString()+ " " + h.toString());

    if (w < 400) {
        userInfo.style.fontSize = "0.8em";
        objktInfo.style.fontSize = "0.8em";
    } else {
        userInfo.style.fontSize = "1em";
        objktInfo.style.fontSize = "1em";
    }
};

window.addEventListener("load", updateSvgSize);
window.addEventListener("resize", updateSvgSize);

var henUsersSketch = function(p) {
    var bgColor = p.color(245);
    var strokeColor = p.color(200, 200, 200, 20);
    var strokeColorAlt = p.color(0, 150, 150);
    var userColor = p.color(20, 60);
    var userColorAlt = p.color(220);
    var selectedUserColor = p.color(100, 240, 100);
    var viewerColor = p.color(100, 100, 240);
    var selectedViewerColor = p.color(50, 50, 255);
    var reportedUserColor = p.color(240, 100, 100);
    var selectedReportedUserColor = p.color(255, 50, 50);
    var altColorMode = false;
    var blockSize = Math.min(w, h) / 5;
    var userCounter = 0;
    var xMin = 0;
    var xMax = 0;
    var yMin = 0;
    var yMax = 0;
    var xCenter = 0;
    var yCenter = 0;
    var zoom = 1;
    var selectedUser;
    var viewer;
    var viewerIndex;
    var chain;

    // Initial setup
    p.setup = function() {
        // Create the users chain
        createChain();

        // Create the canvas
        p.createCanvas(w, h);

        // Set some sketch defaults
        p.rectMode(p.CENTER);
        p.strokeWeight(1);
        p.stroke(altColorMode? strokeColorAlt : strokeColor);
        p.frameRate(60);

        // Start with an empty background
        p.background(bgColor);
    };

    // Execute the sketch
    p.draw = function() {
        var blockSizeChanged, viewerPos;

        // Check if there are still users to draw
        if (userCounter < chain.length) {
            // Calculate the optimal block size to be able to display the current users chain
            blockSizeChanged = updateBlockSize();

            // Draw the user chain again if the block size has changed
            if (blockSizeChanged) {
                drawChain();
            } else {
                // Draw the user block
                drawUser(chain[userCounter]);

                // Check if the current user is the viewer
                if (viewer && userCounter  == viewerIndex) {
                    // Get the viewer position
                    viewerPos = getUserPosition(viewer);

                    // Draw a circle around the viewer
                    p.push();
                    p.stroke(viewerColor);
                    p.noFill();
                    p.circle(viewerPos.x, viewerPos.y, Math.max(30, 4 * zoom * blockSize));
                    p.pop();
                }
            }

            // Display the user information
            displayUserInformation(selectedUser? selectedUser : chain[userCounter]);

            // Increase the user counter
            userCounter++;
        } else {
            // Stop the drawing loop
            p.noLoop();
        }
    };

    // Handle window resizes
    p.windowResized = function() {
        // Resize the canvas
        p.resizeCanvas(w, h);

        // Calculate the optimal block size to be able to display the users chain
        updateBlockSize();

        // Draw the chain
        drawChain();

        // Display the user information
        displayUserInformation(selectedUser);
    };

    // Handle mouse clicks
    p.mouseClicked = function() {
        var i, isViewer, user, userPos, canvasMargin;

        // Unset the previous selected User
        if (selectedUser) {
            selectedUser.color = selectedUser.previousColor;
            selectedUser.colorAlt = selectedUser.previousColorAlt;
            selectedUser = undefined;
        }

        // Find the users that are under the mouse position
        console.log("Users under the mouse position:");
        isViewer = false;

        for (i = 0; i < Math.min(userCounter + 1, chain.length); i++) {
            user = chain[i];
            userPos = getUserPosition(user);

            if (Math.abs(p.mouseX - userPos.x) < zoom * blockSize / 2) {
                if (Math.abs(p.mouseY - userPos.y) < zoom * blockSize / 2) {
                    console.log("  " + user.type + ": " + "https://www.hicetnunc.xyz/tz/" + user.wallet + " " + user.timestamp);
                    selectedUser = user;

                    if (selectedUser.wallet == viewerWallet) {
                        isViewer = true;
                    }
                }
            }
        }

        // Select the viewer if it was under the mouse position
        if (isViewer) {
            selectedUser = viewer;
        }

        if (selectedUser) {
            selectedUser.previousColor = selectedUser.color;
            selectedUser.previousColorAlt = selectedUser.colorAlt;
            selectedUser.color = selectedUser.reported? selectedReportedUserColor : (selectedUser.wallet == viewerWallet)? selectedViewerColor : selectedUserColor;
            selectedUser.colorAlt = selectedUser.color;
        } else {
            console.log("  No users...");
        }

        // Check if the color mode should be changed
        canvasMargin = Math.max(0.1 * Math.min(p.width, p.height), 2 * blockSize);

        if (p.mouseX < canvasMargin && p.mouseY > p.height - canvasMargin) {
            altColorMode = !altColorMode;
            p.stroke(altColorMode? strokeColorAlt : strokeColor);
        }

        // Draw the chain
        drawChain();

        // Display the user information
        displayUserInformation(selectedUser);
    };

    // Handle key inputs
    p.keyPressed = function() {
        var viewerPos;

        // Change the color mode if requested by the user
        if (p.key == " ") {;
            altColorMode = !altColorMode;
            p.stroke(altColorMode? strokeColorAlt : strokeColor);
            drawChain();
       }

        // Draw the complete chain if requested by the user
        if (p.keyCode == p.ENTER) {
            // Calculate the optimal block size to be able to display the complete users chain
            while (userCounter < chain.length) {
                updateBlockSize();
                userCounter++;
            }

            // Draw the chain
            drawChain();

            // Display the user information
            displayUserInformation(selectedUser);
        }

        // Allow the zooming and recentering options only when the complete chain is painted
        if(userCounter == chain.length) {
            if (p.keyCode == p.LEFT_ARROW) {
                xCenter--;
                drawChain();
            } else if (p.keyCode == p.RIGHT_ARROW) {
                xCenter++;
                drawChain();
            } else if (p.keyCode == p.UP_ARROW) {
                yCenter--;
                drawChain();
            } else if (p.keyCode == p.DOWN_ARROW) {
                yCenter++;
                drawChain();
            } else if (p.key == "c" || p.key == "C") {
                xCenter += (p.mouseX - p.width / 2) / (zoom * blockSize);
                yCenter += (p.mouseY - p.height / 2) / (zoom * blockSize);
                drawChain();
            } else if (p.key == "z" || p.key == "Z") {
                //xCenter += (p.mouseX - p.width / 2) / (zoom * blockSize);
                //yCenter += (p.mouseY - p.height / 2) / (zoom * blockSize);
                zoom *= 1.5;
                drawChain();
            } else if (p.key == "x" || p.key == "X") {
                //xCenter += (p.mouseX - p.width / 2) / (zoom * blockSize);
                //yCenter += (p.mouseY - p.height / 2) / (zoom * blockSize);
                zoom /= 1.5;
                drawChain();
            } else if (p.keyCode == p.ESCAPE){
                zoom = 1;
                xCenter = (xMax + xMin) / 2;
                yCenter = (yMax + yMin) / 2;
                drawChain();
            }
        }

        return false;
     };

    // Displays the user information on the screen
    function displayUserInformation(user) {
        if (user) {
            userInfo.style.display = "block";

            if (user.reported) {
                warning.style.display = "block";
            } else {
                warning.style.display = "none";
            }

            henLink.innerHTML = user.wallet.slice(0,5) + "..." + user.wallet.slice(-5);
            henLink.href = "https://www.hicetnunc.xyz/tz/" + user.wallet;

            objktInfo.style.display = "block";
            timestamp.innerHTML = user.timestamp;

            if (user.first_objkt != "") {
                objktLink.style.display = "inline";
                objktLink.innerHTML = "OBJKT#" + user.first_objkt;
                objktLink.href = "https://www.hicetnunc.xyz/objkt/" + user.first_objkt;
            } else {
                objktLink.style.display = "none";
            }
        } else {
            userInfo.style.display = "none";
            objktInfo.style.display = "none";
        }
    }

    // Creates the users chain
    function createChain() {
        var i, user, pos, dir;

        // Fill the chain with the users information
        chain = [];

        for (i = 0; i < users.length; i++) {
            // Get the user
            user = users[i];

            // Calculate the user relative position and direction
            if (i == 0) {
                pos = p.createVector(0, 0);
                dir = p.createVector(1, 0);
            } else {
                pos = pos.copy().add(dir);

                if (user.type == "artist") {
                    dir = dir.copy();
                } else {
                    dir = p.createVector(dir.y, -dir.x);
                    //dir = p.createVector(-dir.y, dir.x);
                }
            }

            // Add the user to the chain
            user.reported = user.reported == 1;
            user.pos = pos;
            user.dir = dir;
            user.color = user.reported? reportedUserColor : userColor;
            user.colorAlt = user.reported? reportedUserColor : userColorAlt;

            if (user.wallet == viewerWallet) {
                user.color = viewerColor;
                user.colorAlt = viewerColor;
                viewer = user;
                viewerIndex = i;
            }

            chain.push(user);
        }
    }

    // Updates the block size to be able to display the complete chain
    function updateBlockSize() {
        var x, y, canvasMargin, requiredWidth, requiredHeight;

        // Update the minimum and maximum (x, y) relative positons
        if (userCounter < chain.length) {
            x = chain[userCounter].pos.x;
            y = chain[userCounter].pos.y;
            xMax = x > xMax? x : xMax;
            xMin = x < xMin? x : xMin;
            yMax = y > yMax? y : yMax;
            yMin = y < yMin? y : yMin;
        }

        // Calculate the optimal block size
        canvasMargin = Math.max(0.1 * Math.min(p.width, p.height), 2 * blockSize);
        requiredWidth = 2 * (blockSize * Math.max(Math.abs(xMax - xCenter), Math.abs(xMin - xCenter)) + canvasMargin);
        requiredHeight = 2 * (blockSize * Math.max(Math.abs(yMax - yCenter), Math.abs(yMin - yCenter)) + canvasMargin);

        if (requiredWidth > p.width || requiredHeight > p.height) {
            if ((requiredWidth - p.width) > (requiredHeight > p.height)) {
                blockSize *= p.width / requiredWidth;
            } else {
                blockSize *= p.height / requiredHeight;
            }

            xCenter = (xMax + xMin) / 2;
            yCenter = (yMax + yMin) / 2;

            return true;
        }

        return false;
    }

    // Gets the user position on the canvas
    function getUserPosition(user) {
        var firstUserPos = p.createVector(p.width / 2 - zoom * blockSize * xCenter, p.height / 2 - zoom * blockSize * yCenter);

        return user.pos.copy().mult(zoom * blockSize).add(firstUserPos);
    }

    // Draws a given user on the canvas
    function drawUser(user) {
        // Get the user position
        var userPos = getUserPosition(user);

        // Draw the user block
        p.fill(altColorMode? user.colorAlt : user.color);
        p.square(userPos.x, userPos.y, zoom * blockSize);
    }

    // Draws the chain on the canvas
    function drawChain() {
        var i, viewerPos;

        // Start with an empty background
        p.background(bgColor);

        // Draw the users
        for (i = 0; i < Math.min(userCounter + 1, chain.length); i++) {
            drawUser(chain[i]);
        }

        // Draw the viewer on top
        if (viewer && userCounter > viewerIndex) {
            // Draw the viewer block
            drawUser(viewer);

            // Get the viewer position
            viewerPos = getUserPosition(viewer);

            // Draw a circle around the viewer
            p.push();
            p.stroke(viewerColor);
            p.noFill();
            p.circle(viewerPos.x, viewerPos.y, Math.max(30, 4 * zoom * blockSize));
            p.pop();
        }
    }
}

window.onload = function() {
    // Print the viewer wallet
    viewerWallet = new URLSearchParams(location.search).get("viewer");

    if (!viewerWallet) {
        viewerWallet = "viewer";
    }

    //viewerWallet = "tz1g6JRCpsEnD2BLiAzPNK3GBD1fKicV9rCx";
    console.log("Viewer wallet:", viewerWallet);

    // Run the sketch
    var sketch = new p5(henUsersSketch);
};
